def solve(inputs: dict) -> float:
    M = inputs.get('matrix')
    n = inputs.get('exponent')
    mod = inputs.get('modulus')

    # Matrix multiplication modulo mod
    def matrix_mult(A, B, mod):
        size = len(A)
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                for k in range(size):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    # Fast exponentiation for matrices
    def matrix_pow(M, exp, mod):
        size = len(M)
        # Identity matrix
        result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        base = [row[:] for row in M]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result_matrix = matrix_pow(M, n, mod)

    # Sum all entries
    total = sum(sum(row) for row in result_matrix)

    return float(total)

